char *strtrim(char *str) {
    int i;
    int len = strlen(str);

    // trim leading whitespace
    for (i = 0; i < len; i++) {
        if (str[i]!='') {
            break;
        }
    }

    // trim trailing whitespace
    for (i = len - 1; i >= 0; i--) {
        if (str[i]!='') {
            break;
        }
    }

    // copy the trimmed string
    char *trimmed = malloc(i + 1);
    strncpy(trimmed, str + i, i);
    trimmed[i] = '\0';

    return trimmed;
}

