char *strtrim(char *str) {
	char *end;
	char *start = str;

	// skip leading spaces
	while (*start =='')
		start++;

	// skip trailing spaces
	end = start + strlen(start) - 1;
	while (end >= start && *end =='')
		end--;

	// write new null terminator
	*end = '\0';

	// return start of trimmed string
	return start;
}

