	if (uid == -1) {
		perror("system");
		return 1;
	}

	// get the home directory from the system
	char home[100] = {0};
	sprintf(command, "getent passwd %s | cut -d: -f6", username);
	int home_len = system(command);
	if (home_len == -1) {
		perror("system");
		return 1;
	}

	// create a pipe
	int pipefd[2];
	if (pipe(pipefd) == -1) {
		perror("pipe");
		return 1;
	}

	// fork a child process
	pid_t pid = fork();
	if (pid == -1) {
		perror("fork");
		return 1;
	}

	// if the child process
	if (pid == 0) {
		// close the write end of the pipe
		close(pipefd[1]);

		// set the user id
		if (setuid(uid) == -1) {
			perror("setuid");
			return 1;
		}

		// change the working directory to the home directory
		if (chdir(home) == -1) {
			perror("chdir");
			return 1;
		}

		// execute the command
		execlp(argv[2], argv[2], NULL);
	}

	// close the read end of the pipe
	close(pipefd[0]);

	// read the output from the child process
	char buffer[100] = {0};
	int bytes_read = 0;
	while ((bytes_read = read(pipefd[0], buffer, 100)) > 0) {
		printf("%s", buffer);
	}

	// wait for the child process to exit
	waitpid(pid, NULL, 0);

	// close the pipe
	close(pipefd[0]);
	close(pipefd[1]);

	return 0;
}

